mapper.select:
SELECT cs.week_day AS weekDay, cs.start_section AS startSection, cs.end_section AS endSection,
       cs.classroom_id AS classroomId,
       o.id AS offeringId, o.teacher_id AS teacherId, o.class_id AS classId,
       cc.course_name AS courseName, t.name AS teacherName,
       c.class_name AS className, cr.room_name AS roomName
FROM course_schedule cs
INNER JOIN course_offering o ON o.id = cs.offering_id AND o.deleted = 0
INNER JOIN course_course cc ON cc.id = o.course_id AND cc.deleted = 0
LEFT JOIN tea_teacher t ON t.id = o.teacher_id
LEFT JOIN base_class c ON c.id = o.class_id
LEFT JOIN base_classroom cr ON cr.id = cs.classroom_id
WHERE o.semester_id = #{semesterId}
  AND cs.offering_id != #{offeringId}
  AND cs.week_day = #{weekDay}
  AND cs.start_section <= #{endSection}
  AND cs.end_section >= #{startSection}
  AND cs.start_week <= #{endWeek}
  AND cs.end_week >= #{startWeek}
  AND (
        (#{teacherId} IS NOT NULL AND o.teacher_id = #{teacherId})
     OR (#{classId} IS NOT NULL AND o.class_id = #{classId})
     OR (#{classroomId} IS NOT NULL AND cs.classroom_id = #{classroomId})
      )
